head.script:
scwin.screenId = "jldods20011";

///////// 1. 변수 및 선언 영역 /////////

scwin.isNew = false;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_if_42", fn: function(){ return (((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sprtRoomDtl" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sprtRoomDtl"))) && typeof (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sprtRoomDtl" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sprtRoomDtl"))).getRowCount === 'function' ? (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sprtRoomDtl" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sprtRoomDtl"))).getRowCount() : (((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sprtRoomDtl" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sprtRoomDtl"))) == null) ? 0 : ((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sprtRoomDtl" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sprtRoomDtl"))).length || 0))) > 0); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.isNew = false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods20011.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldods20011: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.editor = undefined; try { scwin.editor = /* sdd-asis-lifecycle:begin editor — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Dext5editor("dext5editor1")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldods20011' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods20011.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_sprtRoomList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_sprtRoomList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_sprtRoomList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_sprtRoomList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.searchSprtRoom === 'function') { scwin.searchSprtRoom(r["sprtRoomNo"], r["ldMktTpCd"], r["sprtRoomId"], r["webSprtRoomNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.searchSprtRoom (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.searchSprtRoom'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_sprtRoomList.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.input_72_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.input_72_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin input_72_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.reg()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods20011.input_72_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_regNew_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_regNew_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_regNew_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.regNew()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods20011.btn_regNew_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.reg
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.reg = function () {
    /* sdd-asis-lifecycle:begin reg — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const a = DEXT5.getBodyValue("dext5editor1");
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('sprtRoomContn', a) : console.warn('[sdd] hiddenStore 부재: sprtRoomContn'));
    const b = DEXT5.getBodyTextValue("dext5editor1");
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('sprtRoomContnNoHtml', b) : console.warn('[sdd] hiddenStore 부재: sprtRoomContnNoHtml'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('method', "sprtRoomReg") : console.warn('[sdd] hiddenStore 부재: method'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('iSprtRoomTitle', ($c.util.getComponent("ipt_sprtRoomTitle").getValue() || '')) : console.warn('[sdd] hiddenStore 부재: iSprtRoomTitle'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('iChrgInstId', $('#slc_selChrgInstId option:selected').val()) : console.warn('[sdd] hiddenStore 부재: iChrgInstId'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('iLdMktTpCd', $('#slc_selLdMktTpCd option:selected').val()) : console.warn('[sdd] hiddenStore 부재: iLdMktTpCd'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('iSprtRoomGrpId', $('#slc_selSprtRoomGrpId option:selected').val()) : console.warn('[sdd] hiddenStore 부재: iSprtRoomGrpId'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('iSprtRoomId', $('#slc_selSprtRoomId option:selected').val()) : console.warn('[sdd] hiddenStore 부재: iSprtRoomId'));
    $('#headerKeywrdForm')[0].submit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.dext_editor_loaded_event
 * @author Inswave
 * @date 2026. 09. 29
 * @param editor
 * @returns
 * @hidden N
*/
scwin.dext_editor_loaded_event = function (editor) {
    /* sdd-asis-lifecycle:begin dext_editor_loaded_event — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (editor.ID === "dext5editor1") {
        DEXT5.setBodyValue(dma_hiddenStore.get("sprtRoomContn"), editor.ID);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchSprtRoom
 * @author Inswave
 * @date 2026. 09. 29
 * @param sprtRoomNo ldMktTpCd sprtRoomId webSprtRoomNo
 * @returns
 * @hidden N
*/
scwin.searchSprtRoom = function (sprtRoomNo, ldMktTpCd, sprtRoomId, webSprtRoomNo) {
    /* sdd-asis-lifecycle:begin searchSprtRoom — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const curSprtRoomNo = $('#sprtRoomNo').val();
    if (curSprtRoomNo === sprtRoomNo) {
        return;
    }
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('method', "sprtRoom") : console.warn('[sdd] hiddenStore 부재: method'));
    $('#sprtRoomNo').val(sprtRoomNo);
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('iLdMktTpCd', ldMktTpCd) : console.warn('[sdd] hiddenStore 부재: iLdMktTpCd'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('iSprtRoomId', sprtRoomId) : console.warn('[sdd] hiddenStore 부재: iSprtRoomId'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('webSprtRoomNo', webSprtRoomNo) : console.warn('[sdd] hiddenStore 부재: webSprtRoomNo'));
    $('#headerKeywrdForm')[0].submit();
    blockLoading();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.regNew
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.regNew = function () {
    /* sdd-asis-lifecycle:begin regNew — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.isNew = true;
    DEXT5.setBodyValue("", "dext5editor1");
    $('#sprtRoomNo').val("");
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('webSprtRoomNo', "") : console.warn('[sdd] hiddenStore 부재: webSprtRoomNo'));
    $c.util.getComponent('ipt_sprtRoomTitle').setValue("");
    $c.util.getComponent('slc_selChrgInstId').setValue("");
    $c.util.getComponent('slc_selLdMktTpCd').setValue("");
    $c.util.getComponent('slc_selSprtRoomGrpId').setValue("");
    $c.util.getComponent('slc_selSprtRoomId').setValue("");
    /* sdd-asis-lifecycle:end */
};
